import Link from "next/Link";

export default function Cabecalho() {
    return(
        <header className="w-full">
            <div className="bg-black text-fundoClaro text-xs py-2 px-5 flex justify-center md:justify-between items-center text-center">
                <span className="hidden md:inline">
                    Envios internacionais disponiveis - <Link href="/condicoes" className="underline hover:text-dourado">Saiba Mais</Link> | Encomenda Online 24/7 | Multibanco e PayPal aceites
                </span>
            </div>

            <div className="bg-fundoEscuro text-fundoClaro p-5 flex flex-col md:flex-row justify-between items-center shadow-md gap-4">
                <Link href="/" className="text-2xl font-bold">
                    Forma<span className="text-marca">Fantasia</span>
                </Link>

                <nav>
                    <ul className="flex gap-6 font-semibold">
                        <li className="hover:text-marca cursor-pointer transition-colors">Papel</li>
                        <li className="hover:text-marca cursor-pointer transition-colors">Vinil</li>
                        <li className="hover:text-marca cursor-pointer transition-colors">Tapeçarias</li>
                        <li className="hover:text-marca cursor-pointer transition-colors">Outros</li>
                    </ul>
                </nav>

                <div className="flex gap-4 items-center w-full md:w-auto justify-center">
                    <input
                        type="text"
                        placeholder="Buscar..."
                        className="px-3 py-1.5 rounded-md text-black outline-none focus:ring-2 focus:ring-marca w-full md:w-48"
                    />
                    <button className="hover:text-marca transition-colors font-medium">Conta</button>
                    <button className="hover:text-marca transition-colors font-medium">Desejos</button>
                    <button className="hover:text-marca transition-colors font-medium">Carrinho</button>
                </div>
            </div>
        </header>
    );
}